 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            if v:
                counts[v] = counts.get(v, 0) + 1
    base = max(counts, key=counts.get)

    # Locate the main filled panel (the connected component of its background color).
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != base or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = y+dy, x+dx
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == base:
                        seen.add(p)
                        q.append(p)
            comps.append(comp)
    panel = max(comps, key=len)
    r0, r1 = min(r for r,c in panel), max(r for r,c in panel)
    c0, c1 = min(c for r,c in panel), max(c for r,c in panel)
    src = [row[c0:c1+1] for row in grid[r0:r1+1]]
    a, b = len(src), len(src[0])

    outside = [(r,c,grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != 0 and not (r0 <= r <= r1 and c0 <= c <= c1)]
    # The exterior copies of the three labels form the corner arrangement to reproduce.
    guide_colors = {v for r,c,v in outside}
    if len(guide_colors) < 3:
        return src
    gr0, gr1 = min(r for r,c,v in outside), max(r for r,c,v in outside)
    gc0, gc1 = min(c for r,c,v in outside), max(c for r,c,v in outside)
    def corner(r,c, top, left, bottom, right):
        return (0 if r-top <= bottom-r else 2) + (0 if c-left <= right-c else 1)
    target = {}
    for r,c,v in outside:
        target[v] = corner(r,c,gr0,gc0,gr1,gc1)

    # Locate corresponding labels within the panel; each should occupy a distinct corner.
    source = {}
    for r in range(a):
        for c in range(b):
            v = src[r][c]
            if v in target:
                source[v] = (r,c)
    if not all(v in source for v in target):
        return src

    transforms = [
        (lambda r,c:(r,c), a,b),
        (lambda r,c:(r,b-1-c), a,b),
        (lambda r,c:(a-1-r,c), a,b),
        (lambda r,c:(a-1-r,b-1-c), a,b),
        (lambda r,c:(c,r), b,a),
        (lambda r,c:(b-1-c,a-1-r), b,a),
        (lambda r,c:(c,a-1-r), b,a),
        (lambda r,c:(b-1-c,r), b,a),
    ]
    for fn, oh, ow in transforms:
        valid = True
        for v, (r,c) in source.items():
            y,x = fn(r,c)
            # Compare each marker's location to the corresponding output corner.
            pos = corner(y,x,0,0,oh-1,ow-1)
            if pos != target[v]:
                valid = False
                break
        if valid:
            out = [[0]*ow for _ in range(oh)]
            for r in range(a):
                for c in range(b):
                    y,x = fn(r,c)
                    out[y][x] = src[r][c]
            return out
    return src
